(2867673, 401830, 39349, '<td valign="top">Awesome, just wish it were larger.</td>', 'Awesome, just wish it were larger.', '2006-09-27 01:16:03.000000', NULL, 1),
(2867718, 401300, 15711, '<td valign="top">What a cool title. Probably from a song I don''t know. Nice perspective. Love the yellow shoelaces.</td>', 'What a cool title. Probably from a song I don''t know. Nice perspective. Love the yellow shoelaces.', '2006-09-27 01:25:56.000000', NULL, 1),
(2867724, 402246, 15711, '<td valign="top">GREAT title.  What a vista.  WOW - that is beautiful.</td>', 'GREAT title.  What a vista.  WOW - that is beautiful.', '2006-09-27 01:26:23.000000', NULL, 1),
(2867726, 400240, 15711, '<td valign="top">Way oversaturated. I like the idea, but the drops are lost because there isn''t enough contrast.</td>', 'Way oversaturated. I like the idea, but the drops are lost because there isn''t enough contrast.', '2006-09-27 01:26:55.000000', NULL, 1),
(2867740, 400807, 15711, '<td valign="top">Love the title. I like the couple walking out of the shot.</td>', 'Love the title. I like the couple walking out of the shot.', '2006-09-27 01:30:19.000000', NULL, 1),
(2867744, 401728, 48890, '<td valign="top">This rain looks like snow to me. :)</td>', 'This rain looks like snow to me. :)', '2006-09-27 01:31:34.000000', NULL, 1),
(2867747, 402252, 15711, '<td valign="top">Cute. One of the few original, well executed shots in the challenge.</td>', 'Cute. One of the few original, well executed shots in the challenge.', '2006-09-27 01:31:50.000000', NULL, 1),
(2867754, 401738, 17148, '<td valign="top">Great tones...awesome shot</td>', 'Great tones...awesome shot', '2006-09-27 01:32:51.000000', NULL, 1),
(2867761, 401683, 17148, '<td valign="top">Very interestig image...I like it</td>', 'Very interestig image...I like it', '2006-09-27 01:33:38.000000', NULL, 1),
(2867762, 401790, 15711, '<td valign="top">Cute idea but very snapshot like to me. She has the proverbial pole growing out of the top of her head. The stop motion and the yellow boots are cute. Just wish you could have shot it from a different angle.</td>', 'Cute idea but very snapshot like to me. She has the proverbial pole growing out of the top of her head. The stop motion and the yellow boots are cute. Just wish you could have shot it from a different angle.', '2006-09-27 01:33:38.000000', NULL, 1),
(2867768, 401800, 48890, '<td valign="top">Can''t see any rain here.  I see an umbrella, but no rain.</td>', 'Can''t see any rain here.  I see an umbrella, but no rain.', '2006-09-27 01:34:16.000000', NULL, 1),
(2867774, 401796, 15711, '<td valign="top">WOW - what a refreshing change from droplets and puddles.  This is very imaginative.  I like it.  Great use of duotone. 8</td>', 'WOW - what a refreshing change from droplets and puddles.  This is very imaginative.  I like it.  Great use of duotone. 8', '2006-09-27 01:34:38.000000', NULL, 1),
(2867786, 402131, 15711, '<td valign="top">(or in the shower) ;~p  Just kidding.<br/> <br/>Nice focus and lighting.  Great detail on the hands. Great stop action too.</td>', '(or in the shower) ;~p  Just kidding. Nice focus and lighting.  Great detail on the hands. Great stop action too.', '2006-09-27 01:35:53.000000', NULL, 1),
(2867788, 401420, 48890, '<td valign="top">Too much water rolling down the umbrella.  I don''t believe this is real rain.</td>', 'Too much water rolling down the umbrella.  I don''t believe this is real rain.', '2006-09-27 01:36:30.000000', NULL, 1),
(2867790, 402212, 15711, '<td valign="top">What a refreshing change. Love your optimistic look. The wisps of hair in the face help with the movement of the umbrella. Great clarity.  So happy!!!</td>', 'What a refreshing change. Love your optimistic look. The wisps of hair in the face help with the movement of the umbrella. Great clarity.  So happy!!!', '2006-09-27 01:36:47.000000', NULL, 1),
(2867791, 398783, 17148, '<td valign="top">Nice shot...it works well</td>', 'Nice shot...it works well', '2006-09-27 01:36:48.000000', NULL, 1),
(2867795, 402252, 54728, '<td valign="top">Haha.  That''s great!  Her clothing is very bright compared to the dark background and that doesn''t help to convey the emotion of frustration or depression one would be feeling in her situation.  I still like it.</td>', 'Haha.  That''s great!  Her clothing is very bright compared to the dark background and that doesn''t help to convey the emotion of frustration or depression one would be feeling in her situation.  I still like it.', '2006-09-27 01:37:13.000000', NULL, 1),
(2867796, 400807, 17148, '<td valign="top">Shot through a window...it works...like the B&amp;W also</td>', 'Shot through a window...it works...like the B&W also', '2006-09-27 01:37:17.000000', NULL, 1),
(2867804, 402199, 54728, '<td valign="top">Pretty.  I looked at the thumbnail and thought boring, but the large view is so very clear and beautiful.</td>', 'Pretty.  I looked at the thumbnail and thought boring, but the large view is so very clear and beautiful.', '2006-09-27 01:37:56.000000', NULL, 1),
