(2869422, 402046, 51133, '<td valign="top">Very cute!</td>', 'Very cute!', '2006-09-27 14:38:30.000000', NULL, 1),
(2869446, 401320, 51133, '<td valign="top">This is cool - soft, yet harsh (metal) - very nice!</td>', 'This is cool - soft, yet harsh (metal) - very nice!', '2006-09-27 14:46:03.000000', NULL, 1),
