(2869510, 401608, 47541, '<td valign="top">A unique slant on the obligitory water-drop shot in that most of it is blurred - that makes this score higher</td>', 'A unique slant on the obligitory water-drop shot in that most of it is blurred - that makes this score higher', '2006-09-27 15:05:42.000000', NULL, 1),
