(2869518, 401723, 47541, '<td valign="top">While this isnt a unique concept in this challenge the composition you have chosen makes this stand out from the others - good shot!</td>', 'While this isnt a unique concept in this challenge the composition you have chosen makes this stand out from the others - good shot!', '2006-09-27 15:08:51.000000', NULL, 1),
(2869519, 400803, 47541, '<td valign="top">A very good idea and I like the B&amp;W feel.  The plant outside does however take a lot of attention away from the model</td>', 'A very good idea and I like the B&W feel.  The plant outside does however take a lot of attention away from the model', '2006-09-27 15:09:24.000000', NULL, 1),
