(2869529, 400604, 47541, '<td valign="top">Good use of empty space to draw attention to the water drop</td>', 'Good use of empty space to draw attention to the water drop', '2006-09-27 15:12:50.000000', NULL, 1),
(2869530, 402109, 47541, '<td valign="top">I really like this shot but I cant figure out why!  I think its because the umbrellas colour stands out nicely but is not jumping out demanding attention</td>', 'I really like this shot but I cant figure out why!  I think its because the umbrellas colour stands out nicely but is not jumping out demanding attention', '2006-09-27 15:13:46.000000', NULL, 1),
(2869533, 402231, 47541, '<td valign="top">Not a spot of rain to be seen but the lighting in this shot is fantastic.  I''d not have drawn attention to the white horse in the title as that simple enhances the "what has this got to do with rain" feel - I get it though :)</td>', 'Not a spot of rain to be seen but the lighting in this shot is fantastic.  I''d not have drawn attention to the white horse in the title as that simple enhances the "what has this got to do with rain" feel - I get it though :)', '2006-09-27 15:14:53.000000', NULL, 1),
