(2869543, 401784, 47541, '<td valign="top">A nice shot but I''d like to see a wider DOF as the blurred drops seem to be taking charge here</td>', 'A nice shot but I''d like to see a wider DOF as the blurred drops seem to be taking charge here', '2006-09-27 15:17:45.000000', NULL, 1),
(2869544, 398674, 47541, '<td valign="top">Yes it is a cliche but its still a good shot</td>', 'Yes it is a cliche but its still a good shot', '2006-09-27 15:18:06.000000', NULL, 1),
(2869545, 399879, 47541, '<td valign="top">I like the idea of such a closeup on the leaf.  Given this I think this may have been even better if there was nothing but the leaf in frame!</td>', 'I like the idea of such a closeup on the leaf.  Given this I think this may have been even better if there was nothing but the leaf in frame!', '2006-09-27 15:18:46.000000', NULL, 1),
(2869548, 401898, 47541, '<td valign="top">I dont get the title :(</td>', 'I dont get the title :(', '2006-09-27 15:19:11.000000', NULL, 1),
(2869550, 401666, 47541, '<td valign="top">Great choice on the horizon - the barn is a great subject and placing it so low adds so much to the drama created by the clouds</td>', 'Great choice on the horizon - the barn is a great subject and placing it so low adds so much to the drama created by the clouds', '2006-09-27 15:19:44.000000', NULL, 1),
