(2869554, 401478, 47541, '<td valign="top">I feel this shot comes in 2 halves: the top which is average and the bottom with the waves which is full of drama - together they dont seem to work but if you had cropped tighter on the bottom...</td>', 'I feel this shot comes in 2 halves: the top which is average and the bottom with the waves which is full of drama - together they dont seem to work but if you had cropped tighter on the bottom...', '2006-09-27 15:21:24.000000', NULL, 1),
(2869555, 402244, 47541, '<td valign="top">Nice DOF</td>', 'Nice DOF', '2006-09-27 15:21:38.000000', NULL, 1),
