INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2870338, 401386, 63588, '<td valign="top">Not seeing enough of a connection to rain</td>', 'Not seeing enough of a connection to rain', '2006-09-27 20:15:35.000000', NULL, 1),
(2870345, 402218, 63588, '<td valign="top">Nicely shows are dry and needed the rain is for the corn</td>', 'Nicely shows are dry and needed the rain is for the corn', '2006-09-27 20:17:07.000000', NULL, 1),
(2870348, 401758, 63588, '<td valign="top">I find the OOF foreground of the leaf distracting</td>', 'I find the OOF foreground of the leaf distracting', '2006-09-27 20:18:08.000000', NULL, 1),
(2870350, 402082, 63588, '<td valign="top">out of focus</td>', 'out of focus', '2006-09-27 20:18:54.000000', NULL, 1),
(2870353, 402096, 63588, '<td valign="top">seems over processed - can see halos around the leaves/drops. Dramatic.</td>', 'seems over processed - can see halos around the leaves/drops. Dramatic.', '2006-09-27 20:20:37.000000', NULL, 1),
(2870360, 401039, 63588, '<td valign="top">Would have loved this photo if the edge of the tarp/water was in focus. 5</td>', 'Would have loved this photo if the edge of the tarp/water was in focus. 5', '2006-09-27 20:25:15.000000', NULL, 1),
(2870361, 402161, 63639, '<td valign="top">I love how you were able to capture the rain on the grasshopper.  The shot may have been better if you could see some of the background.</td>', 'I love how you were able to capture the rain on the grasshopper.  The shot may have been better if you could see some of the background.', '2006-09-27 20:25:18.000000', NULL, 1),
(2870365, 401683, 40718, '<td valign="top">That''s a good generic title.  I like it better than "...".  The picture is nice.  It''s the first one I''m voting on and that always makes it hard for me, but I like the zoom blur and I think the photo works as an abstract. 7 for now.</td>', 'That''s a good generic title.  I like it better than "...".  The picture is nice.  It''s the first one I''m voting on and that always makes it hard for me, but I like the zoom blur and I think the photo works as an abstract. 7 for now.', '2006-09-27 20:26:50.000000', NULL, 1),
(2870367, 401320, 63639, '<td valign="top">Nice capture!  I love how you captured the flow of the water and the rain.</td>', 'Nice capture!  I love how you captured the flow of the water and the rain.', '2006-09-27 20:27:07.000000', NULL, 1),
(2870368, 401644, 40718, '<td valign="top">You did well to capture the actual rain.  It''s odd how certain parts are much clearer than others.  The blurry bike right in the center is unfortunate, but why is it blurred?  were you panning?  Anyway, captures a feeling well.  Technicals aren''t awesome, but a picture like this doesn''t necessarily need awesome technicals. 6</td>', 'You did well to capture the actual rain.  It''s odd how certain parts are much clearer than others.  The blurry bike right in the center is unfortunate, but why is it blurred?  were you panning?  Anyway, captures a feeling well.  Technicals aren''t awesome, but a picture like this doesn''t necessarily need awesome technicals. 6', '2006-09-27 20:28:24.000000', NULL, 1),
(2870373, 401038, 40718, '<td valign="top">Was it possible to move your perspective somehow so that what was directly behind the spider was lighter?  The lower legs are lost in the background.  Sometimes it is tough and sometimes I cheat and actually put something lighter back there (more leaves, a flower, etc). 5</td>', 'Was it possible to move your perspective somehow so that what was directly behind the spider was lighter?  The lower legs are lost in the background.  Sometimes it is tough and sometimes I cheat and actually put something lighter back there (more leaves, a flower, etc). 5', '2006-09-27 20:29:40.000000', NULL, 1),
(2870374, 401753, 63639, '<td valign="top">This is one of my favorites from this challenge.  Beautiful color and contrast.  Well done.</td>', 'This is one of my favorites from this challenge.  Beautiful color and contrast.  Well done.', '2006-09-27 20:29:44.000000', NULL, 1),
(2870376, 399867, 40718, '<td valign="top">That is one massive rain puddle...</td>', 'That is one massive rain puddle...', '2006-09-27 20:30:12.000000', NULL, 1),
(2870377, 399430, 40718, '<td valign="top">I like the symmetry.  Processing is pretty well done.  the grate adds a neat texture and makes me wonder what we are really seeing. 6</td>', 'I like the symmetry.  Processing is pretty well done.  the grate adds a neat texture and makes me wonder what we are really seeing. 6', '2006-09-27 20:31:02.000000', NULL, 1),
(2870379, 401478, 40718, '<td valign="top">the flat light kills the shot.  a nice capture of the waves though.  pines and firs are really hard to make look good. 4</td>', 'the flat light kills the shot.  a nice capture of the waves though.  pines and firs are really hard to make look good. 4', '2006-09-27 20:31:52.000000', NULL, 1),
(2870382, 402212, 40718, '<td valign="top">he held still pretty well while twirling the bumbershoot.  A bit of a stretch on theme, but whatever. the background is a fairly neat effect.  How do I know he''s a weatherman? 5</td>', 'he held still pretty well while twirling the bumbershoot.  A bit of a stretch on theme, but whatever. the background is a fairly neat effect.  How do I know he''s a weatherman? 5', '2006-09-27 20:32:59.000000', NULL, 1),
(2870384, 400240, 40718, '<td valign="top">the saturation is too much here.  reds really oversaturated quickly on digital.  the highlights are too much too. 4</td>', 'the saturation is too much here.  reds really oversaturated quickly on digital.  the highlights are too much too. 4', '2006-09-27 20:34:08.000000', NULL, 1),
(2870389, 398674, 40718, '<td valign="top">cliche shots always have to be done extremely well to get anywhere.  This one doesn''t quite do it.  I think it''s the DOF and the dark portion which makes it tough. 5</td>', 'cliche shots always have to be done extremely well to get anywhere.  This one doesn''t quite do it.  I think it''s the DOF and the dark portion which makes it tough. 5', '2006-09-27 20:36:19.000000', NULL, 1),
