(2870451, 401738, 51538, '<td valign="top">I think this is my favourite of the challenge. 8.</td>', 'I think this is my favourite of the challenge. 8.', '2006-09-27 21:07:23.000000', NULL, 1),
(2870453, 402231, 51538, '<td valign="top">Lovely sense of impending rain. 8.</td>', 'Lovely sense of impending rain. 8.', '2006-09-27 21:07:39.000000', NULL, 1),
(2870455, 398677, 51538, '<td valign="top">Walking down a New York street this evening I came across such a doll dumped at the side of a bleek street by a trash can and thought of your photo.  Hence back to comment and say I voted 8.</td>', 'Walking down a New York street this evening I came across such a doll dumped at the side of a bleek street by a trash can and thought of your photo.  Hence back to comment and say I voted 8.', '2006-09-27 21:08:34.000000', NULL, 1),
(2870456, 402078, 51538, '<td valign="top">Perfectly pretty.  Not overtly rain but good enough. 8.</td>', 'Perfectly pretty.  Not overtly rain but good enough. 8.', '2006-09-27 21:08:58.000000', NULL, 1),
(2870457, 398783, 51538, '<td valign="top">Suggestive of rain. 7.</td>', 'Suggestive of rain. 7.', '2006-09-27 21:09:13.000000', NULL, 1),
(2870460, 399635, 51538, '<td valign="top">One of my favourites of the challenge.  Lovely colours and effect of fluid. 8.</td>', 'One of my favourites of the challenge.  Lovely colours and effect of fluid. 8.', '2006-09-27 21:09:40.000000', NULL, 1),
(2870462, 401420, 51538, '<td valign="top">A sun showever, right? 7.</td>', 'A sun showever, right? 7.', '2006-09-27 21:10:11.000000', NULL, 1),
(2870464, 401897, 51538, '<td valign="top">Very nice location and shadows.  A favourite of mine. 9.</td>', 'Very nice location and shadows.  A favourite of mine. 9.', '2006-09-27 21:10:49.000000', NULL, 1),
(2870467, 401039, 51538, '<td valign="top">Very good photo - we always without fail camp in rain (for ten years of trips).  I can relate to this in ways you would never predict. 8 for comradeship.  Just wish you had better clarity.  But then again, in such conditions, what are you gonna do!? ;-) 7.</td>', 'Very good photo - we always without fail camp in rain (for ten years of trips).  I can relate to this in ways you would never predict. 8 for comradeship.  Just wish you had better clarity.  But then again, in such conditions, what are you gonna do!? ;-) 7.', '2006-09-27 21:12:05.000000', NULL, 1),
(2870497, 402246, 22537, '<td valign="top">Great shot but no rain.  Dang you for doing this because it is a great shot in the appropriate challenge.  I would have given this a 7 otherwise.</td>', 'Great shot but no rain.  Dang you for doing this because it is a great shot in the appropriate challenge.  I would have given this a 7 otherwise.', '2006-09-27 21:24:16.000000', NULL, 1),
