(2872896, 401309, 51961, '<td valign="top">Color is amazing!</td>', 'Color is amazing!', '2006-09-28 14:28:38.000000', NULL, 1),
(2872953, 401320, 30049, '<td valign="top">My favorite for this challenge.  The red is a nice color pop for what can be a dreary theme (Rain).  The storm drain is a convincing touch that you really were out in rainy conditions.  Well, I suppose you could fake this shot, but unlikely with that much running water.  ;^)  The POV you''ve taken positions the leaf in a prominent location and the lines of the grate work well in the diagonal as you''ve put them.  Nicely done.  Good luck in the challenge.</td>', 'My favorite for this challenge.  The red is a nice color pop for what can be a dreary theme (Rain).  The storm drain is a convincing touch that you really were out in rainy conditions.  Well, I suppose you could fake this shot, but unlikely with that much running water.  ;^)  The POV you''ve taken positions the leaf in a prominent location and the lines of the grate work well in the diagonal as you''ve put them.  Nicely done.  Good luck in the challenge.', '2006-09-28 14:51:43.000000', NULL, 1),
(2872955, 401306, 30049, '<td valign="top">Simple, convincing, fun to look at in an abstract way.  The B/W tone works well with this.  Good luck in the challenge.</td>', 'Simple, convincing, fun to look at in an abstract way.  The B/W tone works well with this.  Good luck in the challenge.', '2006-09-28 14:52:54.000000', NULL, 1),
(2872963, 401683, 30049, '<td valign="top">Funny.  I was going to comment that there are certainly going to be unbelievers on the validity of this image, and there it is - the validation stamp.  ;^)  I finally have a lens that I can zoom while capturing an exposure and had a chance to play with it the other day.  I recognized this in your image immediately.<br/> <br/>I really like the choice you made to do this.  Yes the yellow is quite bright, but it helps balance out the darker tones around the sides.  The streaks at the bottom around the persons legs are wonderful.  Did I mention that I like this?  :D<br/> <br/>Good luck in the challenge.  It will be interesting to see where you end up.</td>', 'Funny.  I was going to comment that there are certainly going to be unbelievers on the validity of this image, and there it is - the validation stamp.  ;^)  I finally have a lens that I can zoom while capturing an exposure and had a chance to play with it the other day.  I recognized this in your image immediately. I really like the choice you made to do this.  Yes the yellow is quite bright, but it helps balance out the darker tones around the sides.  The streaks at the bottom around the persons legs are wonderful.  Did I mention that I like this?  :D Good luck in the challenge.  It will be interesting to see where you end up.', '2006-09-28 14:56:25.000000', NULL, 1),
(2872966, 401897, 30049, '<td valign="top">This has a classic feel to it.  Very nice B/W image captured here.  Well done.</td>', 'This has a classic feel to it.  Very nice B/W image captured here.  Well done.', '2006-09-28 14:57:07.000000', NULL, 1),
(2872972, 400127, 30049, '<td valign="top">Nice color, very crisp and sharp where it counts.  Well composed.  Wish that the blue tone in the lower section was available for the top as well.  That''s my only complaint.  :P  Best of luck to you in the challenge.</td>', 'Nice color, very crisp and sharp where it counts.  Well composed.  Wish that the blue tone in the lower section was available for the top as well.  That''s my only complaint.  :P  Best of luck to you in the challenge.', '2006-09-28 14:59:44.000000', NULL, 1),
(2872980, 400662, 30049, '<td valign="top">This works very well for me.  Could have been a contender for the ''Soft Focus'' challenge with this!  :D  Anyway, you''ve certainly captured the essence of rain in this image.  Nicely done.  Good luck in the challenge.</td>', 'This works very well for me.  Could have been a contender for the ''Soft Focus'' challenge with this!  :D  Anyway, you''ve certainly captured the essence of rain in this image.  Nicely done.  Good luck in the challenge.', '2006-09-28 15:01:47.000000', NULL, 1),
(2872988, 399604, 30049, '<td valign="top">Not sure about the rain part in this.  I believe you, it''s just hard to tell.  I love the blue tone the mist/fog can take on in certain conditions.  The layering of regions makes it look painterly.  That looks like a castle in the midground?  Good luck in the challenge.</td>', 'Not sure about the rain part in this.  I believe you, it''s just hard to tell.  I love the blue tone the mist/fog can take on in certain conditions.  The layering of regions makes it look painterly.  That looks like a castle in the midground?  Good luck in the challenge.', '2006-09-28 15:03:41.000000', NULL, 1),
(2873046, 400121, 64610, '<td valign="top">cute!</td>', 'cute!', '2006-09-28 15:27:33.000000', NULL, 1),
