(2873166, 401752, 9504, '<td valign="top">You are quite the pro.  How professional.  This is stunning and exceptional.  I suspect a ribbon-taker!  10</td>', 'You are quite the pro.  How professional.  This is stunning and exceptional.  I suspect a ribbon-taker!  10', '2006-09-28 16:09:41.000000', NULL, 1),
