(2873223, 401728, 57936, '<td valign="top">WOW That looks cold!!!!!</td>', 'WOW That looks cold!!!!!', '2006-09-28 16:44:44.000000', NULL, 1),
(2873228, 402046, 57936, '<td valign="top">This could be composed better (maybe offset or have a leaf in the watter as well as in hand.) But it is very cute!</td>', 'This could be composed better (maybe offset or have a leaf in the watter as well as in hand.) But it is very cute!', '2006-09-28 16:45:56.000000', NULL, 1),
(2873231, 399446, 29537, '<td valign="top">perhaps better with all the leaf on focus</td>', 'perhaps better with all the leaf on focus', '2006-09-28 16:47:33.000000', NULL, 1),
(2873242, 402252, 53147, '<td valign="top">Back to comment - I am really looking forward to seeing how you accomplished this. I tried several times for something similar and I just couldnt get the water to look right. Nice job with the water and the lighting. One of my favs of the challenge. Well done and Bumping up.</td>', 'Back to comment - I am really looking forward to seeing how you accomplished this. I tried several times for something similar and I just couldnt get the water to look right. Nice job with the water and the lighting. One of my favs of the challenge. Well done and Bumping up.', '2006-09-28 16:51:43.000000', NULL, 1),
(2873253, 400604, 29537, '<td valign="top">why not a vertical framing?</td>', 'why not a vertical framing?', '2006-09-28 16:54:56.000000', NULL, 1),
(2873277, 401897, 29537, '<td valign="top">a suggestive framing</td>', 'a suggestive framing', '2006-09-28 17:00:38.000000', NULL, 1),
(2873694, 399395, 63360, '<td valign="top">Could up the contrast a bit.  I like the composition.</td>', 'Could up the contrast a bit.  I like the composition.', '2006-09-28 19:37:48.000000', NULL, 1),
(2873695, 400712, 63360, '<td valign="top">Lovely composition.  I like the shallow DOF.</td>', 'Lovely composition.  I like the shallow DOF.', '2006-09-28 19:38:46.000000', NULL, 1),
(2873703, 402246, 63360, '<td valign="top">This is gorgeous.  I like how the sun is shining on the foreground, while other parts are shaded by the clouds.  I might have cropped a bit of the sky out.</td>', 'This is gorgeous.  I like how the sun is shining on the foreground, while other parts are shaded by the clouds.  I might have cropped a bit of the sky out.', '2006-09-28 19:42:05.000000', NULL, 1),
(2873711, 400079, 54245, '<td valign="top">I would have liked this more if the streaks were not so visible.</td>', 'I would have liked this more if the streaks were not so visible.', '2006-09-28 19:45:01.000000', NULL, 1),
(2873712, 401667, 63360, '<td valign="top">A little too dark, I think, in the foreground, but the sky is totally awesome!</td>', 'A little too dark, I think, in the foreground, but the sky is totally awesome!', '2006-09-28 19:45:04.000000', NULL, 1),
(2873719, 398677, 63360, '<td valign="top">Looks really desolate here.  I like the sepia tones.</td>', 'Looks really desolate here.  I like the sepia tones.', '2006-09-28 19:47:04.000000', NULL, 1),
(2873722, 401728, 63360, '<td valign="top">Good composition.  The lights in the background distract a bit.</td>', 'Good composition.  The lights in the background distract a bit.', '2006-09-28 19:48:29.000000', NULL, 1),
(2873727, 399881, 63360, '<td valign="top">Cool shot of the water flowing onto the lower leaf.</td>', 'Cool shot of the water flowing onto the lower leaf.', '2006-09-28 19:49:12.000000', NULL, 1),
(2873732, 400079, 63360, '<td valign="top">The idea of rain on the glass is not bad, but the streaks (from wipers?) are very distracting.</td>', 'The idea of rain on the glass is not bad, but the streaks (from wipers?) are very distracting.', '2006-09-28 19:50:48.000000', NULL, 1),
(2873734, 399402, 63360, '<td valign="top">The pattern of raindrops is nice.  Title doesn''t seem to fit.</td>', 'The pattern of raindrops is nice.  Title doesn''t seem to fit.', '2006-09-28 19:51:26.000000', NULL, 1),
(2873736, 401723, 63360, '<td valign="top">Nice shallow DOF.</td>', 'Nice shallow DOF.', '2006-09-28 19:52:01.000000', NULL, 1),
(2873737, 401196, 54245, '<td valign="top">I love this shot but personally do not feel it is really in line with the theme.</td>', 'I love this shot but personally do not feel it is really in line with the theme.', '2006-09-28 19:52:08.000000', NULL, 1),
(2873739, 401306, 63360, '<td valign="top">Concentric rings on the water are nice; the brightness in the center is distracting.</td>', 'Concentric rings on the water are nice; the brightness in the center is distracting.', '2006-09-28 19:53:34.000000', NULL, 1),
(2873740, 401758, 63360, '<td valign="top">I would like to see the entire leaf in focus.</td>', 'I would like to see the entire leaf in focus.', '2006-09-28 19:53:59.000000', NULL, 1),
(2873750, 401897, 63360, '<td valign="top">A bit too much to look at, IMO.  I think that the 2 women with the umbrella should be the focus, so maybe a tighter shot of them.  I like the black/white.</td>', 'A bit too much to look at, IMO.  I think that the 2 women with the umbrella should be the focus, so maybe a tighter shot of them.  I like the black/white.', '2006-09-28 19:58:16.000000', NULL, 1),
(2873751, 402038, 54245, '<td valign="top">Nice shot.  I can not quite tell what the orientation is.</td>', 'Nice shot.  I can not quite tell what the orientation is.', '2006-09-28 19:58:48.000000', NULL, 1),
(2873752, 401608, 63360, '<td valign="top">Seems to have a bit too much glare.  Maybe brighten the photo and add some color.</td>', 'Seems to have a bit too much glare.  Maybe brighten the photo and add some color.', '2006-09-28 19:59:34.000000', NULL, 1),
(2873757, 400673, 54245, '<td valign="top">Lol.  Nice.</td>', 'Lol.  Nice.', '2006-09-28 20:00:08.000000', NULL, 1),
