INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2873764, 401683, 63360, '<td valign="top">I can''t really tell what I''m looking at.</td>', 'I can''t really tell what I''m looking at.', '2006-09-28 20:01:59.000000', NULL, 1),
(2873765, 400566, 63360, '<td valign="top">The glare from the lights is distracting.</td>', 'The glare from the lights is distracting.', '2006-09-28 20:02:35.000000', NULL, 1),
(2873769, 400568, 54245, '<td valign="top">How long did you wait for that to fall.</td>', 'How long did you wait for that to fall.', '2006-09-28 20:04:02.000000', NULL, 1),
(2873772, 399635, 63360, '<td valign="top">I like the blurred effect caused by the rain; Could be improved by cropping a bit of the foreground out.</td>', 'I like the blurred effect caused by the rain; Could be improved by cropping a bit of the foreground out.', '2006-09-28 20:04:45.000000', NULL, 1),
(2873774, 400786, 54245, '<td valign="top">Talk about putting in some effort.</td>', 'Talk about putting in some effort.', '2006-09-28 20:04:56.000000', NULL, 1),
(2873779, 401784, 63360, '<td valign="top">It is difficult to see the droplets that are in focus, maybe because of the angle.  I like the effect of the other raindrops, though.</td>', 'It is difficult to see the droplets that are in focus, maybe because of the angle.  I like the effect of the other raindrops, though.', '2006-09-28 20:06:16.000000', NULL, 1),
(2873786, 400803, 63360, '<td valign="top">I would like to see more of her face.  It would help convey the mood you are trying to create.</td>', 'I would like to see more of her face.  It would help convey the mood you are trying to create.', '2006-09-28 20:08:17.000000', NULL, 1),
(2873787, 401039, 63360, '<td valign="top">Something needs to be in focus here.  I like your idea.</td>', 'Something needs to be in focus here.  I like your idea.', '2006-09-28 20:08:45.000000', NULL, 1),
(2873789, 402252, 54245, '<td valign="top">I love the fact it only looks like it is raining under the umbrella.  Also glad the stick of the umbrella is not right in the middle of her face. Nice shot.<br/>Marty</td>', 'I love the fact it only looks like it is raining under the umbrella.  Also glad the stick of the umbrella is not right in the middle of her face. Nice shot.Marty', '2006-09-28 20:09:40.000000', NULL, 1),
(2873790, 399867, 63360, '<td valign="top">Lovely image, but no rain.  :(</td>', 'Lovely image, but no rain.  :(', '2006-09-28 20:09:54.000000', NULL, 1),
(2873793, 401309, 63360, '<td valign="top">Cool effect on the leaf, but no rain elsewhere?</td>', 'Cool effect on the leaf, but no rain elsewhere?', '2006-09-28 20:10:41.000000', NULL, 1),
(2873796, 401196, 63360, '<td valign="top">Polar bear is beautiful, but no rain.  :(</td>', 'Polar bear is beautiful, but no rain.  :(', '2006-09-28 20:11:50.000000', NULL, 1),
(2873799, 400240, 63360, '<td valign="top">I like the shallow DOF; flower needs to be a bit sharper.</td>', 'I like the shallow DOF; flower needs to be a bit sharper.', '2006-09-28 20:13:39.000000', NULL, 1),
(2873846, 401752, 37104, '<td valign="top">Cool shot, not much about rain though... a little too late for the electricity challenge.</td>', 'Cool shot, not much about rain though... a little too late for the electricity challenge.', '2006-09-28 20:40:39.000000', NULL, 1),
(2873856, 401925, 37104, '<td valign="top">Very nice, only the quality seems a too poor... I love the idea, and it turned out well...</td>', 'Very nice, only the quality seems a too poor... I love the idea, and it turned out well...', '2006-09-28 20:46:18.000000', NULL, 1),
(2873858, 402150, 37104, '<td valign="top">Adorable.</td>', 'Adorable.', '2006-09-28 20:47:34.000000', NULL, 1),
(2873893, 400804, 27763, '<td valign="top">Cute.</td>', 'Cute.', '2006-09-28 21:05:58.000000', NULL, 1),
(2873898, 401738, 27763, '<td valign="top">OK, I''m going to go out on a limb and guess that this is by JJ Beguin.  My second guess is e301.  Am I right?!?!  If not, I apologize.  It''s a nice photo.</td>', 'OK, I''m going to go out on a limb and guess that this is by JJ Beguin.  My second guess is e301.  Am I right?!?!  If not, I apologize.  It''s a nice photo.', '2006-09-28 21:06:38.000000', NULL, 1),
(2873899, 401196, 27763, '<td valign="top">Good title.</td>', 'Good title.', '2006-09-28 21:07:55.000000', NULL, 1),
(2873906, 400121, 27763, '<td valign="top">I like this one.  Nice job.</td>', 'I like this one.  Nice job.', '2006-09-28 21:11:30.000000', NULL, 1),
(2873911, 401683, 27763, '<td valign="top">This is good.</td>', 'This is good.', '2006-09-28 21:12:53.000000', NULL, 1),
(2874000, 402109, 22537, '<td valign="top">Ah heck.  If you had some rain, you''d have done better but I still like the shot. 7 Good luck!</td>', 'Ah heck.  If you had some rain, you''d have done better but I still like the shot. 7 Good luck!', '2006-09-28 21:55:16.000000', NULL, 1),
(2874004, 399430, 22537, '<td valign="top">Beautiful toning and bokeh.  Top 10 for sure.  Good luck.</td>', 'Beautiful toning and bokeh.  Top 10 for sure.  Good luck.', '2006-09-28 21:55:52.000000', NULL, 1),
(2874091, 400613, 22537, '<td valign="top">This is gorgeous.  The fading DOF, colors, stark black background and composition are topnotch. I''d ribbon this shot.  Good luck!</td>', 'This is gorgeous.  The fading DOF, colors, stark black background and composition are topnotch. I''d ribbon this shot.  Good luck!', '2006-09-28 22:27:13.000000', NULL, 1),
(2874100, 401791, 22537, '<td valign="top">This is very cool! I like the use of the Negative space at the bottom  The shot has a rustic feel and the bit of grain is perfect.  I hope this ribbons!</td>', 'This is very cool! I like the use of the Negative space at the bottom  The shot has a rustic feel and the bit of grain is perfect.  I hope this ribbons!', '2006-09-28 22:28:24.000000', NULL, 1),
(2874108, 400712, 22537, '<td valign="top">This a a very solemn image. Simple and well balanced.  Good luck!</td>', 'This a a very solemn image. Simple and well balanced.  Good luck!', '2006-09-28 22:30:08.000000', NULL, 1),
(2874115, 402257, 22537, '<td valign="top">Great focus on the water drop.  It seems intensified and the light within the drop draws me in.  Really good work!</td>', 'Great focus on the water drop.  It seems intensified and the light within the drop draws me in.  Really good work!', '2006-09-28 22:31:58.000000', NULL, 1),
(2874121, 402212, 22537, '<td valign="top">This is just a really good shot and the spinning umbrella works very well.  Best of luck!</td>', 'This is just a really good shot and the spinning umbrella works very well.  Best of luck!', '2006-09-28 22:32:44.000000', NULL, 1),
(2874122, 399604, 22537, '<td valign="top">I like the tonal layers and it looks soooo dreary.  Great presentation.  Good luck.</td>', 'I like the tonal layers and it looks soooo dreary.  Great presentation.  Good luck.', '2006-09-28 22:33:56.000000', NULL, 1),
(2874124, 401320, 22537, '<td valign="top">Really good balance and technical.  I hope you do well!</td>', 'Really good balance and technical.  I hope you do well!', '2006-09-28 22:34:26.000000', NULL, 1),
(2874130, 400695, 22537, '<td valign="top">Such an interesting image.  Good luc!</td>', 'Such an interesting image.  Good luc!', '2006-09-28 22:35:44.000000', NULL, 1),
(2874134, 400327, 22537, '<td valign="top">I HATE cat shots ..... but I like this.  This is really well done.  Good luck! 6</td>', 'I HATE cat shots ..... but I like this.  This is really well done.  Good luck! 6', '2006-09-28 22:36:25.000000', NULL, 1),
(2874146, 401300, 22537, '<td valign="top">I''ve seen many puddle shots and this is among the best.  Great use of perspective.  Good luck!</td>', 'I''ve seen many puddle shots and this is among the best.  Great use of perspective.  Good luck!', '2006-09-28 22:40:32.000000', NULL, 1),
(2874148, 401822, 22537, '<td valign="top">Simple and excellent!  Good luck!</td>', 'Simple and excellent!  Good luck!', '2006-09-28 22:41:17.000000', NULL, 1),
(2874149, 402150, 22537, '<td valign="top">Yeah....I like bug shots.  Bug shot with raindrops are even cooler!  Good luck.</td>', 'Yeah....I like bug shots.  Bug shot with raindrops are even cooler!  Good luck.', '2006-09-28 22:41:52.000000', NULL, 1),
(2874153, 402252, 22537, '<td valign="top">This has got to be a Scalvert shot.  Who else would think of this? I love the concept but I''m not 100% on the image.  Either way, 6.</td>', 'This has got to be a Scalvert shot.  Who else would think of this? I love the concept but I''m not 100% on the image.  Either way, 6.', '2006-09-28 22:43:36.000000', NULL, 1),
(2874157, 400807, 52854, '<td valign="top">Interesting photo -</td>', 'Interesting photo -', '2006-09-28 22:44:09.000000', NULL, 1),
(2874160, 401728, 66310, '<td valign="top">The smile and eyes really bring this photo to life. Excellent choice in the mono also!!</td>', 'The smile and eyes really bring this photo to life. Excellent choice in the mono also!!', '2006-09-28 22:44:54.000000', NULL, 1),
