(2878059, 400327, 62807, '<td valign="top">Nice shot! love the look on the kittys face, how his green eyes shine through the misty glass.</td>', 'Nice shot! love the look on the kittys face, how his green eyes shine through the misty glass.', '2006-09-30 14:44:31.000000', NULL, 1),
(2878060, 401667, 62807, '<td valign="top">Beautiful photo! You can almost smell the rain in the air. Love the colors and crop. Great job!</td>', 'Beautiful photo! You can almost smell the rain in the air. Love the colors and crop. Great job!', '2006-09-30 14:44:41.000000', NULL, 1),
