(2878186, 401308, 57260, '<td valign="top">Nice composition. I would''ve liked to see her face though.</td>', 'Nice composition. I would''ve liked to see her face though.', '2006-09-30 16:26:51.000000', NULL, 1),
(2878191, 401683, 57260, '<td valign="top">Very interesting. Looks almost like an abstract painting. I like it.</td>', 'Very interesting. Looks almost like an abstract painting. I like it.', '2006-09-30 16:31:27.000000', NULL, 1),
