INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2891491, 402038, 54833, '<td valign="top">That is an interesting shot. How did you accomplish that?</td>', 'That is an interesting shot. How did you accomplish that?', '2006-10-03 14:31:19.000000', NULL, 1),
(2891511, 400807, 66490, '<td valign="top">I like how you went black and white. But the whole picture doesn''t hold much interest. At least for me.</td>', 'I like how you went black and white. But the whole picture doesn''t hold much interest. At least for me.', '2006-10-03 14:35:45.000000', NULL, 1),
(2891517, 401723, 66490, '<td valign="top">Cool - great blurry background so that those dew drops just stand out so well. Nice and monochromatic.</td>', 'Cool - great blurry background so that those dew drops just stand out so well. Nice and monochromatic.', '2006-10-03 14:36:46.000000', NULL, 1),
(2891525, 401796, 66490, '<td valign="top">Great blue hue to it all. An interesting perspective - but I''m having a hard time adjusting to the angle. Which way is up?!</td>', 'Great blue hue to it all. An interesting perspective - but I''m having a hard time adjusting to the angle. Which way is up?!', '2006-10-03 14:38:20.000000', NULL, 1),
(2891529, 401752, 66490, '<td valign="top">Nice. Were the trees glowing already, or was that in the basic editing?</td>', 'Nice. Were the trees glowing already, or was that in the basic editing?', '2006-10-03 14:39:10.000000', NULL, 1),
(2891537, 401196, 66490, '<td valign="top">My wife loves Polar Bears! But there isn''t anything new to this. How could you push this further?</td>', 'My wife loves Polar Bears! But there isn''t anything new to this. How could you push this further?', '2006-10-03 14:41:28.000000', NULL, 1),
(2891542, 400568, 66490, '<td valign="top">Very nice!! How long did it take for this? Too bad the drop couldn''t be bigger to take up more space in the bottom half.</td>', 'Very nice!! How long did it take for this? Too bad the drop couldn''t be bigger to take up more space in the bottom half.', '2006-10-03 14:43:02.000000', NULL, 1),
(2891543, 401284, 66490, '<td valign="top">Sorry - but I''ve seen more interesting clouds.</td>', 'Sorry - but I''ve seen more interesting clouds.', '2006-10-03 14:43:36.000000', NULL, 1),
(2891546, 401898, 66490, '<td valign="top">A very nice and peaceful picture. I love panoramics. The colors along the left balance nicely with the other side.</td>', 'A very nice and peaceful picture. I love panoramics. The colors along the left balance nicely with the other side.', '2006-10-03 14:44:46.000000', NULL, 1),
(2891547, 402082, 66490, '<td valign="top">The leaf should take up more space in the top. There''s way too much dead space at the bottom left.</td>', 'The leaf should take up more space in the top. There''s way too much dead space at the bottom left.', '2006-10-03 14:45:23.000000', NULL, 1),
(2891549, 400662, 33672, '<td valign="top">Nice job. I like the comp and the idea.</td>', 'Nice job. I like the comp and the idea.', '2006-10-03 14:46:43.000000', NULL, 1),
(2891552, 401728, 33672, '<td valign="top">Great subject and comp. Lighting is nice and expression is priceless. Nice capture.</td>', 'Great subject and comp. Lighting is nice and expression is priceless. Nice capture.', '2006-10-03 14:47:23.000000', NULL, 1),
(2891575, 400805, 66490, '<td valign="top">Nice setup. With the basic editing - could the candlesticks stand out more?</td>', 'Nice setup. With the basic editing - could the candlesticks stand out more?', '2006-10-03 14:54:48.000000', NULL, 1),
(2891578, 400560, 66490, '<td valign="top">Oooh...racy. Cool notion on showing water and skin - that''s a cool thought.</td>', 'Oooh...racy. Cool notion on showing water and skin - that''s a cool thought.', '2006-10-03 14:55:39.000000', NULL, 1),
(2891579, 399881, 66490, '<td valign="top">I love water in motion - especially when captured in one shot!</td>', 'I love water in motion - especially when captured in one shot!', '2006-10-03 14:56:00.000000', NULL, 1),
(2891582, 401812, 66490, '<td valign="top">I''d love to see this focuse on one or two drops instead of so many.</td>', 'I''d love to see this focuse on one or two drops instead of so many.', '2006-10-03 14:56:29.000000', NULL, 1),
(2891583, 400763, 66490, '<td valign="top">That big grey rock on the left is distracting. Focus on the ripples.</td>', 'That big grey rock on the left is distracting. Focus on the ripples.', '2006-10-03 14:56:54.000000', NULL, 1),
(2891586, 399402, 66490, '<td valign="top">Is that you in the shadow?</td>', 'Is that you in the shadow?', '2006-10-03 14:58:01.000000', NULL, 1),
(2891589, 398869, 66490, '<td valign="top">Great colors!!!</td>', 'Great colors!!!', '2006-10-03 14:58:09.000000', NULL, 1),
(2891778, 399635, 65785, '<td valign="top">if that piece of car at the bottom was clipped out, i think it could be much more effective</td>', 'if that piece of car at the bottom was clipped out, i think it could be much more effective', '2006-10-03 16:39:35.000000', NULL, 1),
(2891823, 402246, 811, '<td valign="top">Nice landscape!  The clouds really add to this.</td>', 'Nice landscape!  The clouds really add to this.', '2006-10-03 16:50:20.000000', NULL, 1),
