(2892093, 400807, 58894, '<td valign="top">This is one of my favorites. I like the distortions and the gloomy rainy day feel. Good luck!</td>', 'This is one of my favorites. I like the distortions and the gloomy rainy day feel. Good luck!', '2006-10-03 17:57:05.000000', NULL, 1),
(2892099, 402252, 58894, '<td valign="top">This was one of my favorites. No one said the rain had to come from the sky. I can''t wait to see how you did this. Good Luck!</td>', 'This was one of my favorites. No one said the rain had to come from the sky. I can''t wait to see how you did this. Good Luck!', '2006-10-03 17:59:00.000000', NULL, 1),
(2892105, 401790, 58894, '<td valign="top">This is a nice shot, however I would love to see the girls expression on her face.</td>', 'This is a nice shot, however I would love to see the girls expression on her face.', '2006-10-03 18:00:01.000000', NULL, 1),
(2892158, 401897, 16126, '<td valign="top">JJ? Anyway, I like it.</td>', 'JJ? Anyway, I like it.', '2006-10-03 18:18:00.000000', NULL, 1),
